        throw new ResponseStatusException(HttpStatus.CONFLICT, "A claim now belongs to a period the rollover generated.");
    }
    if (rollover.getOpeningPeriodId() != null && !rollover.getPeriodIds().contains(rollover.getOpeningPeriodId())) {
        periods.findByIdAndSheetId(rollover.getOpeningPeriodId(), sheetId).ifPresent(period -> {
            rollover.getOpenings().forEach(period::takeOpening);
            periods.saveAndFlush(period);
        });
    }
    periods.deleteAll(made);
    periods.flush();
    rollover.undo();
    rollovers.saveAndFlush(rollover);
    audit.recordOnCommit("ROLLOVER_UNDONE sheet=" + sheetId + " by=" + user + " fy=FY" + rollover.getFy());
}

/**
 * Each person's open figure at the end of a day, by person id: the sum of the due figures of their
 * claims due by in one of the given periods that were OPEN or PENDING then (see {@link #rollover}).
 */
private Map<Long, BigDecimal> openAt(String sheetId, List<Period> within, LocalDate end, LocalDate today) {
    Map<Long, Person> byId = people.findBySheetIdOrderByPositionAscIdAsc(sheetId).stream()
            .collect(Collectors.toMap(Person::getId, person -> person));
    Map<Long, BigDecimal> open = new LinkedHashMap<>();
    for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
        Person person = byId.get(claim.getPersonId());
        if (person == null || within.stream().noneMatch(p -> p.contains(claim.getDueBy()))) {
            continue;
        }
        ClaimStatus then = claim.statusAt(end);
        if (then == null || !then.isOpen() || claim.isDeferredOn(today)
                || (claim.getStatus().isOpen() && !claim.isStated() && person.leavesLive(today))) {
            continue;
        }
        BigDecimal figure = dues.due(claim, person.gradeOn(claim.getDate()));
        if (figure != null) {
            open.merge(person.getId(), figure.setScale(2), BigDecimal::add);
        }
    }
    return open;
}

/**
 * Close a period, fixing at this moment each person's due-total and carried figure (see {@link #carried})
 * for it and its own due-total, their sum. A person's is the sum of the due figures,
 * as computed now, of the claims due by in it that were OPEN, PENDING or SETTLED at the end of its last day by their status log, each at
 * the grade its person has in force on its date (a claim with no figure adds nothing), leaving out those still OPEN or PENDING and dated
 * within their person's hold or of a person whose retirement date is reached, unless bound by a statement, and those deferred on today. Each pool
 * member's cut for it is fixed too, as it stands now (see {@link SheetHistory#cutsNow}). A soft-closed period closes with its figures
 * fixed afresh. Refused when the period is already closed, or for a role the sheet's permission matrix does not allow.
 */
@Transactional
public Period close(String sheetId, String user, long periodId) {
    // Take the sheet's lock first, so no claim in the period changes while its total is fixed.
    LocalDate today = sheets.lock(sheetId).getToday();
    Period period = periods.findByIdAndSheetId(periodId, sheetId)
            .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet."));
    if (!roles.permits(sheetId, user, "close")) {
        throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not close a period.");
    }
    if (period.isClosed()) {
        throw new ResponseStatusException(HttpStatus.CONFLICT, "The period is already closed.");
    }
    return fix(sheetId, user, period, today, "");
}

/**
 * Soft-close an open period: its due-total and each person's figure for it are fixed as on a close
 * (see {@link #close}), while claims due by in it can still be added and changed. Refused when the
 * period is already closed or soft-closed, or for a role the sheet's permission matrix does not
 * allow to close.
 */
@Transactional
public Period softClose(String sheetId, String user, long periodId) {
    LocalDate today = sheets.lock(sheetId).getToday();
    Period period = periods.findByIdAndSheetId(periodId, sheetId)
            .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet."));
    if (!roles.permits(sheetId, user, "close")) {
        throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not close a period.");
    }
    if (period.isFixed()) {
        throw new ResponseStatusException(HttpStatus.CONFLICT, "The period is already closed or soft-closed.");
    }
    period.softClose(totals(sheetId, period, today), carried(sheetId, period, today));
    period.fixCuts(history.cutsNow(sheetId, today));
    Period saved = periods.saveAndFlush(period);
    audit.recordOnCommit("PERIOD_SOFT_CLOSED sheet=" + sheetId + " by=" + user + " period=" + saved.getName()
            + " total=" + saved.getClosedTotal().toPlainString());
    return saved;
}

/**
 * The sheet's today was changed: close, in order of their to-dates, each open period whose to-date
 * plus the sheet's grace days is before the new today, exactly as a close by hand would, its
 * PERIOD_CLOSED marked auto=yes. A soft-closed period keeps the figures fixed for it and is left as
}

public boolean isClosed() {
    return closed;
}

public boolean isSoftClosed() {
    return softClosed;
}

public boolean isLocked() {
    return locked;
}

/** Lock or unlock the period. */
public void setLocked(boolean locked) {
    this.locked = locked;
}

/** Whether the period's figures are fixed: it is closed or soft-closed. */
public boolean isFixed() {
    return closed || softClosed;
}

/** The due-total fixed when the period was closed; null while it is open. */
public BigDecimal getClosedTotal() {
    return closedTotal;
}

/** Each person's due-total fixed when the period was closed, by person id; empty while it is open. */
public Map<Long, BigDecimal> getPersonTotals() {
    return Map.copyOf(personTotals);
}

/** Each person's carried figure fixed when the period was closed, by person id; empty while it is open. */
public Map<Long, BigDecimal> getPersonCarried() {
    return Map.copyOf(personCarried);
}

/** Each person's opening balance for the period, by person id; a person with none is not listed. */
public Map<Long, BigDecimal> getPersonOpenings() {
    return Map.copyOf(personOpenings);
}

/** Add an amount to the person's opening balance for the period. */
public void addOpening(long personId, BigDecimal amount) {
    personOpenings.merge(personId, amount, BigDecimal::add);
}

/** Take an amount back off the person's opening balance for the period; a balance of nothing is removed. */
public void takeOpening(long personId, BigDecimal amount) {
    BigDecimal left = personOpenings.getOrDefault(personId, BigDecimal.ZERO).subtract(amount);
    if (left.signum() == 0) {
        personOpenings.remove(personId);
    } else {
        personOpenings.put(personId, left);
    }
}

/** Close the period, fixing each person's due-total and carried figure for it and its own due-total, their sum. */
public void close(Map<Long, BigDecimal> totals, Map<Long, BigDecimal> carried) {
    fixTotals(totals, carried);
    this.closed = true;
    this.softClosed = false;
}

/** Soft-close the period, fixing its figures as a close does while its claims stay open to change. */
public void softClose(Map<Long, BigDecimal> totals, Map<Long, BigDecimal> carried) {
    fixTotals(totals, carried);
    this.softClosed = true;
}

private void fixTotals(Map<Long, BigDecimal> totals, Map<Long, BigDecimal> carried) {
    this.personTotals.clear();
    this.personTotals.putAll(totals);
    this.personCarried.clear();
    this.personCarried.putAll(carried);
    this.closedTotal = totals.values().stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
}

/** What the period's pool cuts were fixed from when it was closed, as JSON; null while it is open. */
public String getCuts() {
    return cuts;
}

/** Fix what the period's pool cuts are worked out from, as JSON. */
public void fixCuts(String cuts) {
    this.cuts = cuts;
}

/** Reopen the period: its due-total and pool cuts are live again. */
public void reopen() {
    this.cuts = null;
    this.closed = false;
    this.softClosed = false;
    this.closedTotal = null;
    this.personTotals.clear();
    this.personCarried.clear();
}

